SELECT order_id, amount,
  amount - LAG(amount) OVER (
    PARTITION BY customer_id
    ORDER BY order_date, order_id
  ) AS change
FROM orders;

SELECT price_date,
  NVL(price,
    LAG(price) IGNORE NULLS
    OVER (ORDER BY price_date)
  ) AS filled_price
FROM price_history;
